<?php
require_once __DIR__ . '/../includes/functions.php'; require_login();$user=current_user();
$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$month)||!DateTime::createFromFormat('!Y-m',$month))$month=date('Y-m');
$first=new DateTime($month.'-01');$start=clone $first;$start->modify('monday this week');$end=clone $start;$end->modify('+41 days');
$stmt=db()->prepare('SELECT t.*,s.name subject_name FROM study_tasks t LEFT JOIN subjects s ON s.id=t.subject_id AND s.user_id=t.user_id WHERE t.user_id=? AND t.due_date BETWEEN ? AND ? ORDER BY t.due_date, FIELD(t.priority,"high","medium","low")');$stmt->execute([$user['id'],$start->format('Y-m-d'),$end->format('Y-m-d')]);$byDate=[];foreach($stmt->fetchAll() as $t)$byDate[$t['due_date']][]=$t;
$prev=(clone $first)->modify('-1 month')->format('Y-m');$next=(clone $first)->modify('+1 month')->format('Y-m');$pageTitle='Calendar';$activePage='calendar';require __DIR__.'/../includes/header.php';
?>
<section class="page-heading reveal"><div><div class="eyebrow">SEE THE BIG PICTURE</div><h1>Your calendar</h1><p>Deadlines are easier to manage when you can see them coming.</p></div><a class="btn btn-primary" href="add_task.php">＋ Add task</a></section>
<section class="panel reveal"><div class="panel-header"><div><h2 class="panel-title"><?= e($first->format('F Y')) ?></h2><p class="panel-subtitle">Tasks with a deadline appear on their due date.</p></div><div class="calendar-toolbar"><a class="btn btn-secondary btn-small" href="calendar.php?month=<?= e($prev) ?>" aria-label="Previous month">←</a><a class="btn btn-secondary btn-small" href="calendar.php">Today</a><a class="btn btn-secondary btn-small" href="calendar.php?month=<?= e($next) ?>" aria-label="Next month">→</a></div></div>
<div class="calendar-grid"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day): ?><div class="calendar-day-name"><?= $day ?></div><?php endforeach; ?><?php $cursor=clone $start;for($i=0;$i<42;$i++):$key=$cursor->format('Y-m-d');$sameMonth=$cursor->format('Y-m')===$first->format('Y-m');$today=$key===date('Y-m-d'); ?><div class="calendar-cell <?= !$sameMonth?'muted-day':'' ?> <?= $today?'today':'' ?>"><div class="calendar-date"><strong><?= $cursor->format('j') ?></strong><span><?= $today?'Today':'' ?></span></div><?php foreach(array_slice($byDate[$key]??[],0,3) as $t): ?><a class="calendar-task <?= $t['status']==='completed'?'completed':'' ?> <?= $t['priority']==='high'?'high':'' ?>" href="add_task.php?id=<?= (int)$t['id'] ?>" title="<?= e($t['title']) ?>"><?= e($t['title']) ?></a><?php endforeach; ?><?php if(count($byDate[$key]??[])>3): ?><span class="calendar-task">+<?= count($byDate[$key])-3 ?> more</span><?php endif; ?></div><?php $cursor->modify('+1 day');endfor; ?></div>
<div class="mini-legend" style="margin-top:15px"><span><i class="legend-dot"></i>Pending task</span><span><i class="legend-dot" style="background:var(--success)"></i>Completed task</span><span style="color:var(--error)">▎ High priority</span></div>
</section>
